const input = $input.first().json;
const normalize = (value) => String(value || '').replace(/\s+/g, ' ').trim();
const tokenize = (value) => new Set(normalize(value).toLowerCase().match(/[a-z0-9$%.-]+/g) || []);
const fingerprint = (value) => {
  let hash = 2166136261;
  for (const char of normalize(value)) {
    hash ^= char.charCodeAt(0);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
};

const before = normalize(input.previous_text);
const after = normalize(input.current_text);
if (!before || !after) throw new Error('Both previous_text and current_text are required.');

const beforeTokens = tokenize(before);
const afterTokens = tokenize(after);
const added = [...afterTokens].filter((token) => !beforeTokens.has(token)).slice(0, 12);
const removed = [...beforeTokens].filter((token) => !afterTokens.has(token)).slice(0, 12);
const changed = before !== after;
const deltaSize = added.length + removed.length;

return [{
  json: {
    page_label: String(input.page_label || 'Unlabeled page'),
    page_url: String(input.page_url || ''),
    status: changed ? 'changed' : 'unchanged',
    previous_fingerprint: fingerprint(before),
    current_fingerprint: fingerprint(after),
    added_terms: added,
    removed_terms: removed,
    change_size: deltaSize === 0 ? 'none' : deltaSize <= 3 ? 'small' : deltaSize <= 8 ? 'medium' : 'large',
    alert_summary: changed
      ? `${input.page_label || 'Page'} changed: ${added.length} added term(s), ${removed.length} removed term(s).`
      : `${input.page_label || 'Page'} has no normalized text change.`,
    checked_at: new Date().toISOString()
  }
}];
